        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        int n = Integer.parseInt(br.readLine().trim());
        String store = br.readLine().trim();  // 가게 이름

        int count = 0;
        for (int t = 0; t < n; t++) {
            String sign = br.readLine().trim();  // 간판 문자열

            boolean found = false;
            int storeLen = store.length();
            int signLen = sign.length();

            // 모든 시작 위치 시도
            for (int start = 0; start < signLen && !found; start++) {
                if (sign.charAt(start) != store.charAt(0)) continue;

                // 모든 간격 시도
                int maxStep = storeLen > 1 ? (signLen - 1 - start) / (storeLen - 1) : signLen;
                for (int step = 1; step <= maxStep && !found; step++) {
                    boolean match = true;
                    for (int i = 0; i < storeLen; i++) {
                        int pos = start + i * step;
                        if (pos >= signLen || sign.charAt(pos) != store.charAt(i)) {
                            match = false;
                            break;
                        }
                    }
                    if (match) found = true;
                }
            }

            if (found) count++;
        }

        System.out.println(count);
    }
}

