def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def find_prime_ap(n):
    # 간단한 등차수열 탐색
    # 시작점과 공차를 바꿔가며 탐색
    for start in range(2, 10000):
        if not is_prime(start):
            continue
        for d in range(1, 1000):
            count = 0
            seq = []
            for k in range(n):
                val = start + k * d
                if is_prime(val):
                    count += 1
                    seq.append(val)
                else:
                    break
            if count >= n:
                return seq[:n]
    return None

