    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        N = Integer.parseInt(st.nextToken());
        P = Integer.parseInt(st.nextToken());
        L = Long.parseLong(st.nextToken());

        villages = new long[N];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) {
            villages[i] = Long.parseLong(st.nextToken());
        }

        minDist = Long.MAX_VALUE;
        bestSelection = new int[P];
        int[] current = new int[P];

        // 모든 조합 시도
        combination(0, 0, current);

        StringBuilder sb = new StringBuilder();
        sb.append(minDist).append('\n');
        for (int i = 0; i < P; i++) {
            sb.append(villages[bestSelection[i]]);
            if (i < P - 1) sb.append(' ');
        }
        System.out.println(sb);
    }

    static void combination(int start, int depth, int[] current) {
        if (depth == P) {
            long dist = calcDist(current);
            if (dist < minDist) {
                minDist = dist;
                System.arraycopy(current, 0, bestSelection, 0, P);
            }
            return;
        }

        for (int i = start; i < N; i++) {
            current[depth] = i;
            combination(i + 1, depth + 1, current);
        }
    }

    static long calcDist(int[] selected) {
        long total = 0;
        for (int i = 0; i < N; i++) {
            long minD = Long.MAX_VALUE;
            for (int s : selected) {
                minD = Math.min(minD, Math.abs(villages[i] - villages[s]));
            }
            total += minD;
        }
        return total;
    }
}

