import java.io.*;
import java.math.BigInteger;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();

        // 피보나치 수 미리 계산
        List<BigInteger> fib = new ArrayList<>();
        fib.add(BigInteger.ZERO);
        fib.add(BigInteger.ONE);

        BigInteger limit = new BigInteger("10").pow(18);
        while (fib.get(fib.size() - 1).compareTo(limit) < 0) {
            int size = fib.size();
            fib.add(fib.get(size - 1).add(fib.get(size - 2)));
        }

        // 피보나치 -> 인덱스 맵
        Map<BigInteger, Integer> fibToIdx = new HashMap<>();
        for (int i = 0; i < fib.size(); i++) {
            fibToIdx.put(fib.get(i), i);
        }

        int T = Integer.parseInt(br.readLine().trim());
        while (T-- > 0) {
            BigInteger n = new BigInteger(br.readLine().trim());

            if (fibToIdx.containsKey(n)) {
                sb.append(fibToIdx.get(n)).append('\n');
            } else {
                // 이분 탐색
                int lo = 0, hi = fib.size() - 1;
                while (lo < hi) {
                    int mid = (lo + hi) / 2;
                    if (fib.get(mid).compareTo(n) < 0) {
                        lo = mid + 1;
                    } else {
                        hi = mid;
                    }
                }
                sb.append(lo).append('\n');
            }
        }

        System.out.print(sb);
    }
}

