int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    // 피보나치 수 미리 계산
    vector<ull> fib;
    fib.push_back(0);
    fib.push_back(1);

    while (fib.back() < 1e18) {
        fib.push_back(fib[fib.size()-1] + fib[fib.size()-2]);
    }

    // 피보나치 -> 인덱스 맵
    map<ull, int> fibToIdx;
    for (int i = 0; i < (int)fib.size(); i++) {
        fibToIdx[fib[i]] = i;
    }

    int T;
    cin >> T;

    while (T--) {
        ull n;
        cin >> n;

        if (fibToIdx.count(n)) {
            cout << fibToIdx[n] << '\n';
        } else {
            // 이분 탐색
            int lo = 0, hi = fib.size() - 1;
            while (lo < hi) {
                int mid = (lo + hi) / 2;
                if (fib[mid] < n) {
                    lo = mid + 1;
                } else {
                    hi = mid;
                }
            }
            cout << lo << '\n';
        }
    }

    return 0;
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();

        int T = Integer.parseInt(br.readLine().trim());
        while (T-- > 0) {
            char[] arr = br.readLine().trim().toCharArray();
            int n = arr.length;

            // 뒤에서부터 감소하지 않는 위치 찾기
            int i = n - 2;
            while (i >= 0 && arr[i] >= arr[i + 1]) {
                i--;
            }

            if (i < 0) {
                // 이미 가장 큰 수
                sb.append("BIGGEST\n");
            } else {
                // arr[i]보다 큰 가장 작은 수를 뒤에서 찾기
                int j = n - 1;
                while (arr[j] <= arr[i]) {
                    j--;
                }

                // 교환
                char temp = arr[i];
                arr[i] = arr[j];
                arr[j] = temp;

                // i+1부터 끝까지 뒤집기
                int left = i + 1, right = n - 1;
                while (left < right) {
                    temp = arr[left];
                    arr[left] = arr[right];
                    arr[right] = temp;
                    left++;
                    right--;
                }

                sb.append(new String(arr)).append('\n');
            }
        }

        System.out.print(sb);
    }
}

