        int i = n - 2;
        while (i >= 0 && s[i] >= s[i + 1]) {
            i--;
        }

        if (i < 0) {
            // 이미 가장 큰 수
            cout << "BIGGEST\n";
        } else {
            // s[i]보다 큰 가장 작은 수를 뒤에서 찾기
            int j = n - 1;
            while (s[j] <= s[i]) {
                j--;
            }

            // 교환
            swap(s[i], s[j]);

            // i+1부터 끝까지 뒤집기
            reverse(s.begin() + i + 1, s.end());

            cout << s << '\n';
        }
