public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();

        int T = Integer.parseInt(br.readLine().trim());
        for (int tc = 1; tc <= T; tc++) {
            int N = Integer.parseInt(br.readLine().trim());
            int[] prices = new int[2 * N];

            StringTokenizer st = new StringTokenizer(br.readLine());
            for (int i = 0; i < 2 * N; i++) {
                prices[i] = Integer.parseInt(st.nextToken());
            }
            Arrays.sort(prices);

            // 카운터 맵
            Map<Integer, Integer> cnt = new HashMap<>();
            for (int p : prices) {
                cnt.put(p, cnt.getOrDefault(p, 0) + 1);
            }

            List<Integer> original = new ArrayList<>();

            for (int p : prices) {
                if (cnt.getOrDefault(p, 0) <= 0) continue;

                // p는 원래 가격
                cnt.put(p, cnt.get(p) - 1);
                original.add(p);

                // 할인 가격 = p * 3 / 4
                int discounted = p * 3 / 4;
                cnt.put(discounted, cnt.get(discounted) - 1);
            }

            sb.append("Case #").append(tc).append(": ");
            for (int i = 0; i < original.size(); i++) {
                sb.append(original.get(i));
                if (i < original.size() - 1) sb.append(' ');
            }
            sb.append('\n');
        }

        System.out.print(sb);
    }
}

