# 회문수: N 이하의 회문수이면서 회문수의 거듭제곱인 수의 개수
import sys

def is_palindrome(n):
    s = str(n)
    return s == s[::-1]

def count_palindrome_powers(N):
    # 1은 모든 수의 1제곱이므로 포함
    result = set()
    result.add(1)

    # 각 회문수의 거듭제곱 확인
    for base in range(2, int(N**0.5) + 2):
        if not is_palindrome(base):
            continue

        power = base
        while power <= N:
            if is_palindrome(power):
                result.add(power)
            power *= base
            if power > N:
                break

    # 회문수 자체도 1제곱이므로 포함
    for i in range(1, N + 1):
        if is_palindrome(i):
            result.add(i)

    return len(result)

