import java.io.*;
import java.util.*;

public class Main {
    static String getSignature(String word) {
        if (word.length() <= 2) {
            return word + "||";
        }
        char[] middle = word.substring(1, word.length() - 1).toCharArray();
        Arrays.sort(middle);
        return word.charAt(0) + "|" + word.charAt(word.length() - 1) + "|" + new String(middle);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        int N = Integer.parseInt(br.readLine().trim());
        Map<String, String> sigToWord = new HashMap<>();

        for (int i = 0; i < N; i++) {
            String word = br.readLine().trim();
            String sig = getSignature(word);
            sigToWord.put(sig, word);
        }

        int M = Integer.parseInt(br.readLine().trim());
        String[] scrambled = br.readLine().trim().split(" ");

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < M; i++) {
            String sig = getSignature(scrambled[i]);
            if (sigToWord.containsKey(sig)) {
                sb.append(sigToWord.get(sig));
            } else {
                sb.append(scrambled[i]);
            }
            if (i < M - 1) sb.append(' ');
        }

        System.out.println(sb);
    }
}

