string getSignature(const string& word) {
    if (word.length() <= 2) {
        return word + "||";
    }
    string middle = word.substr(1, word.length() - 2);
    sort(middle.begin(), middle.end());
    return string(1, word[0]) + "|" + string(1, word[word.length() - 1]) + "|" + middle;
}

int main() {
