        string sig = getSignature(word);
        sigToWord[sig] = word;
    }

    int M;
    cin >> M;

    for (int i = 0; i < M; i++) {
        string word;
        cin >> word;
        string sig = getSignature(word);

        if (sigToWord.count(sig)) {
            cout << sigToWord[sig];
        } else {
            cout << word;
        }
