    }
    cout << '\n';

    return 0;
}

import java.io.*;
import java.util.*;

public class Main {
    static String[] words = new String[6];
    static String result = null;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        for (int i = 0; i < 6; i++) {
            words[i] = br.readLine().trim();
        }

        // 6개 단어 중 3개를 가로로 선택하는 모든 순열
        int[] perm = new int[3];
        boolean[] used = new boolean[6];
        permute(0, perm, used);

        if (result != null) {
            System.out.println(result);
        } else {
            System.out.println(0);
        }
    }

    static void permute(int depth, int[] perm, boolean[] used) {
        if (depth == 3) {
            check(perm);
            return;
        }

        for (int i = 0; i < 6; i++) {
            if (!used[i]) {
                used[i] = true;
                perm[depth] = i;
                permute(depth + 1, perm, used);
                used[i] = false;
            }
        }
    }

    static void check(int[] perm) {
        String[] rows = new String[3];
        for (int i = 0; i < 3; i++) {
            rows[i] = words[perm[i]];
        }

        // 세로 단어 생성
        String[] cols = new String[3];
        for (int i = 0; i < 3; i++) {
            cols[i] = "" + rows[0].charAt(i) + rows[1].charAt(i) + rows[2].charAt(i);
        }

        // 나머지 단어와 비교
        List<String> remaining = new ArrayList<>();
        boolean[] usedInPerm = new boolean[6];
        for (int p : perm) usedInPerm[p] = true;
        for (int i = 0; i < 6; i++) {
            if (!usedInPerm[i]) remaining.add(words[i]);
        }

        Collections.sort(remaining);
        String[] colsSorted = cols.clone();
        Arrays.sort(colsSorted);

        boolean match = true;
        for (int i = 0; i < 3; i++) {
            if (!remaining.get(i).equals(colsSorted[i])) {
                match = false;
                break;
            }
        }

        if (match) {
            String grid = rows[0] + "\n" + rows[1] + "\n" + rows[2];
            if (result == null || grid.compareTo(result) < 0) {
                result = grid;
            }
        }
    }
}

