void check(vector<int>& perm) {
    string rows[3];
    for (int i = 0; i < 3; i++) {
        rows[i] = words[perm[i]];
    }

    // 세로 단어 생성
    string cols[3];
    for (int i = 0; i < 3; i++) {
        cols[i] = string() + rows[0][i] + rows[1][i] + rows[2][i];
    }

    // 나머지 단어와 비교
    vector<string> remaining;
    vector<bool> usedInPerm(6, false);
    for (int p : perm) usedInPerm[p] = true;
    for (int i = 0; i < 6; i++) {
        if (!usedInPerm[i]) remaining.push_back(words[i]);
    }

    sort(remaining.begin(), remaining.end());
    vector<string> colsSorted(cols, cols + 3);
    sort(colsSorted.begin(), colsSorted.end());

    bool match = true;
    for (int i = 0; i < 3; i++) {
        if (remaining[i] != colsSorted[i]) {
            match = false;
            break;
        }
    }

    if (match) {
        string grid = rows[0] + "\n" + rows[1] + "\n" + rows[2];
        if (!found || grid < result) {
            result = grid;
            found = true;
        }
    }
}

void permute(int depth, vector<int>& perm, vector<bool>& used) {
    if (depth == 3) {
        check(perm);
        return;
    }

    for (int i = 0; i < 6; i++) {
        if (!used[i]) {
            used[i] = true;
            perm.push_back(i);
            permute(depth + 1, perm, used);
            perm.pop_back();
            used[i] = false;
        }
    }
}

